text = input("Adkhil darajat al-harara lil-yawm: ")
today = float(text)  
#Khatwa 2: Andhar al-mustakhdim bi-taghayyurat darajat al-harara
if  today < yesterday :
    print("Al-jaww yusbiho abard!")
else :
    if  today > yesterday :
        print("Al-jaww yusbiho asakhun!")
    else :
        print("Darajat al-harara nafs al-ams!")

